#include <iostream>
#include <string>
#include <vector>
using namespace std;

template <typename T>
class Pouch {
public:
    void put(T x) { goods.push_back(x); }
    T at(int i) { return goods[i]; }
private:
    vector<T> goods;
};

int main() {
    Pouch<string> p;
    p.put("{name}");
    cout << p.at(0) << endl;
    return 0;
}
